cd /private/var/folders/yw/fbsfvfm95956m4m6yfd49z_c0000gn/T/tair-expanded-project-vy2v94nu/workspace && node --input-type=module -e "
import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup preserving first occurrence and order
const a = uniqueStrings(['apple', 'banana', 'apple', 'cherry', 'banana']);
console.log('basic:', JSON.stringify(a));
console.assert(JSON.stringify(a) === JSON.stringify(['apple','banana','cherry']), 'basic failed');

// Case-insensitive dedup, original spelling preserved
const b = uniqueStrings(['Hello', 'hello', 'HELLO', 'World', 'world']);
console.log('case:', JSON.stringify(b));
console.assert(JSON.stringify(b) === JSON.stringify(['Hello','World']), 'case failed');

// Whitespace not trimmed
const c = uniqueStrings(['  a', 'a', '  a', 'a  ']);
console.log('whitespace:', JSON.stringify(c));
console.assert(JSON.stringify(c) === JSON.stringify(['  a','a','a  ']), 'whitespace failed');

// Input not mutated
const input = ['x', 'X', 'y', 'x'];
const snapshot = [...input];
uniqueStrings(input);
console.assert(JSON.stringify(input) === JSON.stringify(snapshot), 'mutation failed');

// Empty input
console.log('empty:', JSON.stringify(uniqueStrings([])));

// Non-ASCII unaffected (toLowerCase still applied)
const d = uniqueStrings(['É', 'é', 'E', 'e']);
console.log('accent:', JSON.stringify(d));

console.log('All checks passed.');
"

